INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','adjective-order','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"adjective-order","title":"Adjectives: position, order and noun phrases","level":"A2","order":21,"summary":"Describe nouns clearly and recognise the usual ordering of several adjectives.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Before a noun or after a linking verb","Usual adjective order","Linking verbs take descriptive adjectives","Restricted positions"],"rules":[{"title":"Before a noun or after a linking verb","explanation":"Many adjectives can come before a noun or after be, seem and other linking verbs. They describe a quality of the noun or subject. English adjectives do not normally change for plural number.","pattern":"a **quiet** room / The rooms are **quiet**.","commonMistakes":["Quiet rooms does not become quiets rooms. Number is normally marked on the noun."],"examples":["Describe the task’s quality: “The plan to prepare the visitor guide sounds **useful**.”","Describe the task’s quality: “The plan to restore the old portrait sounds **useful**.”"],"skill":"form"},{"title":"Usual adjective order","explanation":"A useful neutral order is opinion, size, age, shape, colour, origin, material, purpose, then noun. This is a strong tendency rather than an absolute law. Writers may change order for emphasis or grouping, and long strings are usually avoided.","pattern":"a **lovely small old wooden** box","commonMistakes":["Do not overload a noun with every category; two or three relevant details are normally clearer."],"examples":["Complete the plural noun phrase: “We need **clear** instructions to prepare the visitor guide.”","Complete the plural noun phrase: “We need **clear** instructions to restore the old portrait.”"],"skill":"meaning"},{"title":"Linking verbs take descriptive adjectives","explanation":"After a linking verb, an adjective describes the subject rather than the manner of an action. Compare The soup smells good with She smells the flower carefully. The verb’s role determines the modifier.","pattern":"The plan **sounds useful**.","commonMistakes":["Sounds usefully is not the normal way to say the plan itself seems useful."],"examples":["Choose the usual neutral adjective order for the box of supplies used to prepare the visitor guide. → **a small old wooden box**","Choose the usual neutral adjective order for the box of supplies used to restore the old portrait. → **a small old wooden box**"],"skill":"contrast"},{"title":"Restricted positions","explanation":"Some adjectives commonly prefer one position. Asleep and afraid are usually predicative: the child is asleep. Main and former usually come before nouns. Learn these restrictions with the individual adjective rather than assuming every adjective moves freely.","pattern":"the **main** road / The child is **asleep**.","commonMistakes":["An asleep child is less usual than a sleeping child; dictionary examples help with such lexical restrictions."],"examples":["Choose an adjective after be: “The assistant is **afraid** of preparing the visitor guide alone.”","Choose an adjective after be: “The assistant is **afraid** of restoring the old portrait alone.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"4574d1fd-6c0a-56a9-a0ce-35a7e5f665a9","topicSlug":"adjective-order","level":"A2","prompt":"Describe the task’s quality: “The plan to prepare the visitor guide sounds ____.”","choices":[{"id":"A","text":"usefulness"},{"id":"B","text":"use"},{"id":"C","text":"useful"},{"id":"D","text":"usefully"}],"answerId":"C","hint":"The sentence evaluates **the plan**, not how someone makes a sound.","explanation":"Sounds is a linking verb here, so **useful** describes the plan.","keywords":["adjective-linking"],"skill":"adjective-linking","contextKey":"adjective-order-1","fingerprint":"95242ac1026a98bd3a5c0f5d3019f67116cbe4456718b52e20a7222d9237ce57","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The sentence evaluates **the plan**, not how someone makes a sound.","Sounds is a linking verb here, so **useful** describes the plan.","Choose **useful**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Usefulness is a noun, not the required adjective.","B":"Use is not the descriptive adjective needed here.","C":"Sounds is a linking verb here, so **useful** describes the plan.","D":"Usefully is an adverb and would describe manner, not the plan’s quality after linking sounds."}}},{"id":"f562aa51-32fc-526a-a4aa-178ec3ba3c84","topicSlug":"adjective-order","level":"A2","prompt":"Complete the plural noun phrase: “We need ____ instructions to prepare the visitor guide.”","choices":[{"id":"A","text":"clearness"},{"id":"B","text":"clear"},{"id":"C","text":"clears"},{"id":"D","text":"clearly"}],"answerId":"B","hint":"The noun is plural, but the **adjective stays unchanged**.","explanation":"The adjective **clear** does not change to match plural instructions.","keywords":["adjective-number"],"skill":"adjective-number","contextKey":"adjective-order-1","fingerprint":"536522037c3b178ff901a42d15f64b30ca916d3781b5266214061239e89c782e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The noun is plural, but the **adjective stays unchanged**.","The adjective **clear** does not change to match plural instructions.","Choose **clear**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Clearness is a noun and does not supply this adjective.","B":"The adjective **clear** does not change to match plural instructions.","C":"Adjectives do not normally add a plural -s in English.","D":"Clearly is an adverb, not the adjective before instructions."}}},{"id":"d3cdc445-8a92-5b4e-ac1e-817b54809b40","topicSlug":"adjective-order","level":"A2","prompt":"Choose the usual neutral adjective order for the box of supplies used to prepare the visitor guide.","choices":[{"id":"A","text":"a small wooden olds box"},{"id":"B","text":"a small old wooden box"},{"id":"C","text":"a wooden old small box"},{"id":"D","text":"an old wooden small box"}],"answerId":"B","hint":"Order these categories: **size, age, material**.","explanation":"The ordinary sequence here is **size → age → material → noun**.","keywords":["neutral-adjective-order"],"skill":"neutral-adjective-order","contextKey":"adjective-order-1","fingerprint":"e6fca462cebf4eef21e0e865d58f16d52fcf31b3dfd79f4c3054ecfce1adc769","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Order these categories: **size, age, material**.","The ordinary sequence here is **size → age → material → noun**.","Choose **a small old wooden box**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Old does not take a plural -s and normally precedes the material adjective.","B":"The ordinary sequence here is **size → age → material → noun**.","C":"This reverses the usual size–age–material ordering.","D":"Small normally comes before age and material in the neutral sequence."}}},{"id":"2625aeec-b203-598c-a0a7-a517cba9367b","topicSlug":"adjective-order","level":"A2","prompt":"Choose an adjective after be: “The assistant is ____ of preparing the visitor guide alone.”","choices":[{"id":"A","text":"fear"},{"id":"B","text":"fearfully"},{"id":"C","text":"afraids"},{"id":"D","text":"afraid"}],"answerId":"D","hint":"The slot after **is** describes a state and is followed by the preposition **of**.","explanation":"**Afraid of** is a predicative adjective pattern describing the assistant’s state.","keywords":["predicative-adjective"],"skill":"predicative-adjective","contextKey":"adjective-order-1","fingerprint":"647e9a59e2284ee2fad3a8cca6922747246adb4a562c3ceb77b76857e809d74f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The slot after **is** describes a state and is followed by the preposition **of**.","**Afraid of** is a predicative adjective pattern describing the assistant’s state.","Choose **afraid**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Fear is a noun or verb, not this adjective after is.","B":"Fearfully is an adverb and does not fill the adjective slot.","C":"Afraid does not take an -s ending.","D":"**Afraid of** is a predicative adjective pattern describing the assistant’s state."}}},{"id":"6a919a26-dda0-5623-a48c-e66756e4ca58","topicSlug":"adjective-order","level":"A2","prompt":"Describe the task’s quality: “The plan to restore the old portrait sounds ____.”","choices":[{"id":"A","text":"usefully"},{"id":"B","text":"usefulness"},{"id":"C","text":"use"},{"id":"D","text":"useful"}],"answerId":"D","hint":"The sentence evaluates **the plan**, not how someone makes a sound.","explanation":"Sounds is a linking verb here, so **useful** describes the plan.","keywords":["adjective-linking"],"skill":"adjective-linking","contextKey":"adjective-order-2","fingerprint":"8bcc5c833dcdea757788851f93e290b9a1396